        "value": {
          "material": "论文讨论了分子模拟、代谢产物等其他机制，并将本研究的转移机制置于更广泛的微生物-免疫互作背景下。"
        },
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::7183fab48388d36a56b62d98"
        ]
      },
      {
        "atom_id": "atom::f592b8502fe014b1c0ed734b",
        "source_handle": "P0166",
        "field_path": [
